\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{graphicx}
\usepackage{booktabs}

\title{Active Learning for Mineral Prospectivity Mapping in Arid Terrains}
\author{L.~Abara and D.~Petrosyan}
\date{July 2026}

\begin{document}
\maketitle
\section{Introduction}\label{introduction}
Porphyry exploration in arid terrains remains expensive and uncertain, and active learning is the most practical lever for focusing field budgets without retraining legacy models. Section~\ref{sec-method} details our approach.
\begin{figure}[t]
\centering
\IfFileExists{figures/overview.pdf}{\includegraphics[width=0.8\columnwidth]{figures/overview.pdf}}{\rule{0.8\columnwidth}{3.2cm}}
\caption{Study blocks and known occurrences grouped by deposit family.}\label{fig:teaser}
\end{figure}

\section{Geological Setting}\label{SEC:geology}
We build on regional geophysics and on legacy stream-sediment surveys. The prior model scores cells by expert weighting, and the learner conditions on the top-$k$ evidence layers stacked with the coordinates.

\section{Method}\label{sec-method}
Figure~\ref{Fig:architecture} summarises the pipeline.
\begin{figure}[t]
\centering
\IfFileExists{figures/pipeline.pdf}{\includegraphics[width=0.9\columnwidth]{figures/pipeline.pdf}}{\rule{0.9\columnwidth}{3.2cm}}
\caption{The query-by-committee pipeline with prospectivity fusion.}\label{Fig:architecture}
\end{figure}
The acquisition weight for cell $j$ and the training objective are
\begin{equation}
\alpha_j = \operatorname{softmax}(g^\top F_j / \sqrt{d}), \label{eq:acquisition}
\end{equation}
\begin{equation}
\mathcal{L} = \mathcal{L}_{\mathrm{cls}} + \lambda \mathcal{L}_{\mathrm{cons}}, \label{equation:objective}
\end{equation}
with the softmax normalisation and a stabilising regulariser given by
\begin{equation}
p_j = \frac{\exp(s_j)}{\sum_{l} \exp(s_l)}, \label{eq:softmax}
\end{equation}
\begin{equation}
\mathcal{R} = \|F\|_F^2 + \|g\|_2^2. \label{Eq:regularizer}
\end{equation}
The derivation of the update rule is deferred to Appendix~\ref{app:derivations}.
Committee scoring uses the margin, and the fused utility combines it with the prior prospectivity map:
\begin{equation}
s_j = g^\top F_j, \label{eq:margin}
\end{equation}
\begin{equation}
U_j = s_j + \beta \log \pi_{\theta}(y \mid x, j). \label{eq:utility}
\end{equation}
An auxiliary loss aligns the committee members, and the labelling cost is linear in the batch size:
\begin{equation}
\mathcal{L}_{\mathrm{aux}} = 1 - \cos(g, F_{+}), \label{eq:loss-aux}
\end{equation}
\begin{equation}
T = O(b \cdot N \cdot d). \label{eq:complexity}
\end{equation}

\section{Survey Data}\label{sec:data}
We compiled twelve survey blocks spanning four terrain units; the campaigns of Table~\ref{table:sites} total 41 thousand line-kilometres after harmonisation. Table~\ref{tab:commodities} lists the target commodities.
\begin{table}[t]
\centering
\caption{Survey statistics per terrain unit.}\label{table:sites}
\begin{tabular}{lrr}
\toprule
Unit & Blocks & Lines (K) \\
\midrule
Bajada & 4 & 14.2 \\
Pediment & 3 & 11.8 \\
\bottomrule
\end{tabular}
\end{table}
\begin{table}[t]
\centering
\caption{Target commodities and their evidence layers.}\label{tab:commodities}
\begin{tabular}{ll}
\toprule
Commodity & Layers \\
\midrule
Copper & 9 \\
Lithium & 5 \\
\bottomrule
\end{tabular}
\end{table}

\section{Experiments}\label{sec:Experiments}
We fine-tune the model of Section~\ref{sec-method} for 30 rounds with entropy querying. Table~\ref{tab:hyperparams} reports the hyperparameters.
\begin{table}[t]
\centering
\caption{Hyperparameters for all reported runs.}\label{tab:hyperparams}
\begin{tabular}{lr}
\toprule
Parameter & Value \\
\midrule
Learning rate & $3 \times 10^{-5}$ \\
Batch size & 256 \\
\bottomrule
\end{tabular}
\end{table}

\section{Results}\label{results-section}
Figure~\ref{figure:scoremap} visualises the learned prospectivity, and Table~\ref{tab:main-results} reports the main comparison.
\begin{figure}[t]
\centering
\IfFileExists{figures/scoremap.pdf}{\includegraphics[width=0.75\columnwidth]{figures/scoremap.pdf}}{\rule{0.75\columnwidth}{3.0cm}}
\caption{Prospectivity scores for a validation block with three known occurrences.}\label{figure:scoremap}
\end{figure}
\begin{table}[t]
\centering
\caption{Discovery rate on the held-out blocks.}\label{tab:main-results}
\begin{tabular}{lr}
\toprule
System & DR \\
\midrule
Static prior & 31.4 \\
Ours & 46.9 \\
\bottomrule
\end{tabular}
\end{table}
Figure~\ref{fig:qualitative} shows a qualitative example.
\begin{figure}[t]
\centering
\IfFileExists{figures/qualitative.pdf}{\includegraphics[width=0.8\columnwidth]{figures/qualitative.pdf}}{\rule{0.8\columnwidth}{3.0cm}}
\caption{Ranked cells for a held-out catchment.}\label{fig:qualitative}
\end{figure}

\section{Ablations}\label{sec:ablations}
All ablations follow the labelling protocol of Section~\ref{sec:Experiments}.
Table~\ref{tab_ablation} ablates each component, and Figure~\ref{fig:scaling} plots the scaling behaviour.
\begin{table}[t]
\centering
\caption{Ablation results on the development blocks.}\label{tab_ablation}
\begin{tabular}{lr}
\toprule
Variant & DR \\
\midrule
Full model & 46.9 \\
No auxiliary loss & 44.1 \\
\bottomrule
\end{tabular}
\end{table}
\begin{figure}[t]
\centering
\IfFileExists{figures/scaling.pdf}{\includegraphics[width=0.75\columnwidth]{figures/scaling.pdf}}{\rule{0.75\columnwidth}{3.0cm}}
\caption{Discovery rate as a function of labelling budget.}\label{fig:scaling}
\end{figure}
\section{Related Work}\label{sec:related}
Our setting is closest to recent work on active surveying for under-mapped terrains, and, as motivated in Section~\ref{introduction}, we prioritise methods that require no additional drilling.
\section{Conclusion}\label{sec:conclusion}
Active querying closes much of the exploration gap, and the gains of Section~\ref{results-section} hold across all four terrain units.

\appendix
\section{Acquisition Derivations}\label{app:derivations}
We bound the gradient of the objective in \eqref{equation:objective}. Under the regulariser of \eqref{Eq:regularizer}, the gradient satisfies
\begin{equation}
\|\nabla \mathcal{L}\| \le G \sqrt{d}, \label{eq:gradient}
\end{equation}
which yields the contraction bound
\begin{equation}
\mathbb{E}[\mathcal{L}_T] - \mathcal{L}^{*} \le \frac{G^2 d}{T}, \label{eq:bound}
\end{equation}
completing the derivation sketched for \eqref{equation:objective}.
\end{document}

